from collections import Counter

PRICE = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}


def total(basket):
    # Naive greedy: always take the largest possible group.
    counts = sorted(Counter(basket).values(), reverse=True)
    while len(counts) < 5:
        counts.append(0)
    total = 0
    while counts[0] > 0:
        distinct = sum(1 for c in counts if c > 0)
        size = min(distinct, 5)
        total += PRICE[size]
        for i in range(size):
            counts[i] -= 1
        counts = sorted(counts, reverse=True)
    return total

