from collections import Counter
from functools import lru_cache
from itertools import combinations

# Price (in cents) of a group of `size` distinct books.
PRICE = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}


def total(basket):
    """Return the cheapest total price (in cents) for the given basket.

    The five books are interchangeable except for how many copies of each
    title are present, so the state is fully described by the multiset of
    per-title counts. We sort the counts in non-increasing order and memoise
    over that canonical tuple, trying every way of forming the next group.
    """
    counts = Counter(basket)
    start = tuple(sorted((counts.get(i, 0) for i in range(1, 6)), reverse=True))
    start += (0,) * (5 - len(start))

    @lru_cache(maxsize=None)
    def dp(state):
        if state[0] == 0:
            return 0
        best = float("inf")
        for size in range(1, 6):
            if state[size - 1] == 0:
                # Fewer than `size` distinct titles remain.
                continue
            for idxs in combinations(range(5), size):
                if any(state[i] == 0 for i in idxs):
                    continue
                nxt = list(state)
                for i in idxs:
                    nxt[i] -= 1
                nxt = tuple(sorted(nxt, reverse=True))
                cost = PRICE[size] + dp(nxt)
                if cost < best:
                    best = cost
        return best

    return dp(start)

